.section .text
.globl _start
.option norvc
j debug_rom
.align 3
j debug_exception
.align 7
.option rvc
_start:
h0_start:
                  li x10, 0x40001104
                  csrw 0x301, x10
kernel_sp:        
                  la x12, kernel_stack_end

trap_vec_init:    
                  la x10, mtvec_handler
                  ori x10, x10, 1
                  csrw 0x305, x10 # MTVEC

pmp_setup:        
                  csrwi 0x747, 4
