                  csrw 0x3be, x2
                  li x2, 0x594cf46
                  csrw 0x3bf, x2
                  li x2, 0x850f1b0b
                  csrw 0x3a3, x2
                  csrwi 0x747, 2

mepc_setup:       
                  la x10, init
                  csrw 0x341, x10

custom_csr_setup: 
                  csrwi 0x7c0, 1

init_machine_mode:
                  li x10, 0x21800
                  csrw 0x300, x10 # MSTATUS
                  li x10, 0x0
                  csrw 0x304, x10 # MIE
                  li x29, 0x8ffffffc
                  li x10, 0x300
                  slli x10, x10, 8
                  addi x10, x10, 0x3
                  sw x10, 0(x29)
                  csrr x10, 0x300
                  sw x10, 0(x29)
                  li x29, 0x8ffffffc
                  li x10, 0x304
                  slli x10, x10, 8
                  addi x10, x10, 0x3
                  sw x10, 0(x29)
                  csrr x10, 0x304
                  sw x10, 0(x29)
                  mret
init:             
                  li x0, 0x0
                  li x1, 0x0
                  li x2, 0xf55ae986
                  li x3, 0x80000000
                  li x4, 0x6
                  li x5, 0x3
                  li x6, 0xf4f77d4b
                  li x7, 0xb
                  li x8, 0x2e3a97b
                  li x9, 0x2
