                  li x23, 0x0
                  li x24, 0x0
                  li x25, 0x0
                  li x27, 0x35fbfb61
                  li x28, 0xfcf45d11
                  li x29, 0x5
                  li x30, 0xd
                  li x31, 0xfd54d360
                  la x26, user_stack_end
                  li x29, 0x8ffffffc
                  li x10, 0x0
                  slli x10, x10, 8
                  addi x10, x10, 0x0
                  sw x10, 0(x29)
                  j main
test_done:        
                  li x29, 0x8ffffff8
                  li x10, 0x0
                  slli x10, x10, 8
                  addi x10, x10, 0x1
                  sw x10, 0(x29)
                  ecall

test_fail:        
                  li x29, 0x8ffffff8
                  li x10, 0x1
                  slli x10, x10, 8
                  addi x10, x10, 0x1
                  sw x10, 0(x29)
                  ecall

